<?php declare(strict_types=1);namespace App\Services;use App\Core\DB;use App\Core\Mailer;final class JobService{public static function push(string $w,array $K,int $y=0):int{return DB::insert('jobs',['queue'=>$w,'payload'=>$K,'available_at'=>gmdate('Y-m-d H:i:s',time()+$y),'created_at'=>now()]);}public static function process(int $g=50):int{$Q=DB::fetchAll('SELECT * FROM {{jobs}} WHERE failed_at IS NULL AND reserved_at IS NULL AND available_at <= ? ORDER BY id LIMIT '.(int)$g,[now()]);$m=0;foreach($Q as $c){DB::update('jobs',['reserved_at'=>now(),'attempts'=>(int)$c['attempts']+1],'id = ?',[$c['id']]);$V=json_decode((string)$c['payload'],true)?:[];try{if($c['queue']==='mail'){$O=(new Mailer())->sendTemplate($V['to'],$V['template'],$V['data']??[],$V['lang']??'fr',$V['name']??null);if(!$O){throw new \RuntimeException('envoi échoué');}}DB::delete('jobs','id = ?',[$c['id']]);$m++;}catch(\Throwable $h){$s=(int)$c['attempts']+1>=3;DB::update('jobs',['reserved_at'=>null,'error'=>$h->getMessage(),'failed_at'=>$s?now():null,'available_at'=>gmdate('Y-m-d H:i:s',time()+600)],'id = ?',[$c['id']]);}}return $m;}public static function pendingCount():int{return(int)DB::scalar('SELECT COUNT(*) FROM {{jobs}} WHERE failed_at IS NULL');}public static function failedCount():int{return(int)DB::scalar('SELECT COUNT(*) FROM {{jobs}} WHERE failed_at IS NOT NULL');}}